let glCompileShader : GLuint -> unit =
  foreign "glCompileShader" (GLuint @-> returning void)

let glGetShaderiv : GLuint -> GLenum -> GLint ptr -> unit =
  foreign "glGetShaderiv"
    (GLuint @-> GLenum @-> ptr GLint @-> returning void)

let glCreateProgram : unit -> GLuint =
  foreign "glCreateProgram" (unit @-> returning GLuint)

let glAttachShader : GLuint -> GLuint -> unit =
  foreign "glAttachShader" (GLuint @-> GLuint @-> returning void)

let glLinkProgram : GLuint -> unit =
  foreign "glLinkProgram" (GLuint @-> returning void)

let glGetProgramiv : GLuint -> GLenum -> GLint ptr -> unit =
  foreign "glGetProgramiv"
    (GLuint @-> GLenum @-> ptr GLint @-> returning void)

let glUseProgram : GLuint -> unit =
  foreign "glUseProgram" (GLuint @-> returning void)

let glDispatchCompute : GLuint -> GLuint -> GLuint -> unit =
  foreign "glDispatchCompute"
    (GLuint @-> GLuint @-> GLuint @-> returning void)

let glFinish : unit -> unit =
  foreign "glFinish" (unit @-> returning void)

let main () =
  (* Initialize GLUT and create window *)
  ignore (glutInit Sys.argv);
  glutInitDisplayMode [GLUT_DOUBLE; GLUT_RGBA];
  glutInitWindowSize 800, 600;
  let win = glutCreateWindow "Dot Product Compute Shader" in
  if win < 0 then exit 1;

  (* Create and compile the compute shader *)
  let shader = glCreateShader GL_COMPUTE_SHADER in
  let source = [| "#version 430 core\n\
                   layout(local_size_x = 1) in;\n\
                   layout(binding = 0) buffer Input {\n\
                     vec4 data[];\n\
                   } input;\n\
                   layout(binding = 1) buffer Output {\n\
                     float result;\n\
                   } output;\n\
                   void main() {\n\
                     int i = gl_GlobalInvocationID.x;\n\
                     float sum = 0.0;\n\
                     for (int j = 0; j < 2; ++j) {\n\
                       sum += input.data[i * 2 + j].x;\n\
                     }\n\
                     output.result = sum;\n\
                   }"; |] in
  glShaderSource shader 1 source [];
  glCompileShader shader;

  (* Check for compilation errors *)
  let status = malloc sizeof GLint in
  glGetShaderiv shader GL_COMPILE_STATUS status;
  if !status <> 1 then begin
    printf "Error compiling shader: %s\n" (glGetShaderInfoLog shader);
    exit 1
  end;

  (* Create and link the program *)
  let program = glCreateProgram () in
  glAttachShader program shader;
  glLinkProgram program;

  (* Check for linking errors *)
  glGetProgramiv program GL_LINK_STATUS status;
  if !status <> 1 then begin
    printf "Error linking program: %s\n" (glGetProgramInfoLog program);
    exit 1
  end;

  (* Use the program *)
  glUseProgram program;

  (* Dispatch the compute shader *)
  glDispatchCompute 1 1 1;
  glFinish ();

  (* Clean up resources *)
  glDeleteShader shader;
  glDeleteProgram program;

  (* Main loop *)
  glutMainLoop ()

let () = main ()
