To extract text from a document in JavaScript, you can use various libraries depending on the format of your document (e.g., PDF, DOCX). Below are examples for extracting text from PDF and DOCX files using popular libraries.

### Extracting Text from a PDF

For PDFs, you can use the `pdf-lib` library to read the content. First, install the library:

```bash
npm install pdf-lib
```

Then, create a function to extract text:

```javascript
const { PDFDocument } = require('pdf-lib');

async function extractTextFromPDF(filePath) {
    const existingPdfBytes = await Deno.readFile(filePath);
    const pdfDoc = await PDFDocument.load(existingPdfBytes);

    let extractedText = '';

    // Iterate through each page
    for (let i = 0; i < pdfDoc.getPageCount(); i++) {
        const page = pdfDoc.getPage(i);
        const textContent = await page.getTextContent();
        extractedText += textContent.items.map(item => item.str).join(' ');
    }

    return extractedText;
}

// Example usage:
extractTextFromPDF('example.pdf').then(text => console.log(text));
```

### Extracting Text from a DOCX

For DOCX files, you can use the `mammoth` library. First, install the library:

```bash
npm install mammoth
```

Then, create a function to extract text:

```javascript
const mammoth = require("mammoth");

function extractTextFromDOCX(filePath) {
    return new Promise((resolve, reject) => {
        mammoth.extractRawText({ path: filePath })
            .then(result => resolve(result.value))
            .catch(error => reject(error));
    });
}

// Example usage:
extractTextFromDOCX('example.docx').then(text => console.log(text));
```

