#include <vector>
#include <cmath>

extern "C" {
    void applyReverb(float* inputBuffer, float* outputBuffer, int bufferSize, const std::vector<float>& impulseResponse) {
        // Apply convolution reverb
        for (int i = 0; i < bufferSize; ++i) {
            float sum = 0.0f;
            for (size_t j = 0; j < impulseResponse.size(); ++j) {
                if ((i - j) >= 0 && (i - j) < bufferSize) {
                    sum += inputBuffer[i - j] * impulseResponse[j];
                }
            }
            outputBuffer[i] = sum;
        }
    }
}
```

