            // Save the favorite to the session
            session()->push('favorites', $name);
            return true;
        }
    }

    /**
     * Remove a name from the favorites list.
     *
     * @param string $name The name to remove.
     * @return bool True if successful, false otherwise.
     */
    public function removeName(string $name): bool
    {
        // Check if there's a logged-in user
        if (Auth::check()) {
            // Delete the favorite from the database
            return Favorite::where('user_id', Auth::id())
                ->where('name', $name)
                ->delete();
