Creating a smart contract for an ERC-1155 token with credentials (creds) involves several steps, including defining the token's properties, implementing the necessary functions, and ensuring security measures are in place. Below is a simplified example of how you might structure such a smart contract using Solidity.

Please note that this is a basic example and should be thoroughly audited before deployment to ensure it meets your specific requirements and adheres to best practices.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CredsToken is ERC1155, Ownable {
    // Event to log when a new credential type is added
    event CredentialTypeAdded(uint256 indexed id, string name);

    // Mapping from credential ID to its metadata URI
    mapping(uint256 => string) private _credentialMetadata;

    constructor() ERC1155("https://example.com/api/v1/creds/{id}.json") {}

    /**
     * @dev Mints a specified amount of tokens of a given ID to a recipient.
     * This function can only be called by the owner or approved addresses.
     */
    function mintCred(
        address account,
        uint256 id,
        uint256 amount,
        bytes memory data
    ) public onlyOwnerOrApproved(id) {
        _mint(account, id, amount, data);
    }

    /**
     * @dev Burns a specified amount of tokens of a given ID from a sender.
     * This function can only be called by the owner or approved addresses.
     */
    function burnCred(
        address account,
        uint256 id,
        uint256 amount,
        bytes memory data
    ) public onlyOwnerOrApproved(id) {
        _burn(account, id, amount);
    }

    /**
     * @dev Adds a new credential type with associated metadata.
     * Only the contract owner can call this function.
     */
    function addCredentialType(uint256 id, string memory metadataURI)
        external
        onlyOwner
    {
        require(bytes(_credentialMetadata[id]).length == 0, "Credential already exists");
        _credentialMetadata[id] = metadataURI;
        emit CredentialTypeAdded(id, "");
    }

    /**
     * @dev Returns the metadata URI for a given credential ID.
     */
    function getCredentialMetadata(uint256 id) external view returns (string memory) {
        return _credentialMetadata[id];
    }

    /**
     * @dev Checks if the caller is either the owner or has been approved for a specific credential ID.
     */
    modifier onlyOwnerOrApproved(uint256 id) {
        require(owner() == msg.sender || isApprovedForAll(msg.sender, id), "Not authorized");
        _;
    }
}
```

### Key Points:
- **Inheritance**: The contract inherits from `ERC1155` and `Ownable`, which provides essential functionality for managing multiple token types and ownership.
- **Events**: An event `CredentialTypeAdded` is emitted whenever a new credential type is added.
- **Minting and Burning**: Functions `mintCred` and `burnCred` allow for minting and burning tokens, respectively. These operations are restricted to the contract owner or approved addresses.
- **Adding Credential Types**: The `addCredentialType` function allows the owner to add new credential types along with their metadata URIs.
- **Metadata Retrieval**: The `getCredentialMetadata` function retrieves the metadata URI for a given credential ID.
- **Authorization Check**: The `onlyOwnerOrApproved` modifier ensures that only the contract owner or approved addresses can perform certain actions.

