```python
import numpy as np

# Constants for player and empty cells
PLAYER1 = 1
PLAYER2 = 2
EMPTY = 0

def create_board():
    return np.zeros((6, 7), dtype=int)

def drop_piece(board, row, col, piece):
    board[row][col] = piece

def is_valid_location(board, col):
    return board[5][col] == EMPTY

def get_next_open_row(board, col):
    for r in range(6):
        if board[r][col] == EMPTY:
            return r

def print_board(board):
    print(np.flip(board, 0))

def winning_move(board, piece):
    # Check horizontal locations for win
    for c in range(4):
        for r in range(6):
            if board[r][c] == piece and board[r][c+1] == piece and board[r][c+2] == piece and board[r][c+3] == piece:
                return True

    # Check vertical locations for win
    for c in range(7):
        for r in range(3):
            if board[r][c] == piece and board[r+1][c] == piece and board[r+2][c] == piece and board[r+3][c] == piece:
                return True

    # Check positively sloped diagonals
    for c in range(4):
        for r in range(3):
            if board[r][c] == piece and board[r+1][c+1] == piece and board[r+2][c+2] == piece and board[r+3][c+3] == piece:
                return True

    # Check negatively sloped diagonals
    for c in range(4):
        for r in range(3, 6):
            if board[r][c] == piece and board[r-1][c+1] == piece and board[r-2][c+2] == piece and board[r-3][c+3] == piece:
                return True

def main():
    board = create_board()
    game_over = False
    turn = PLAYER1

    while not game_over:
        print_board(board)

        if turn == PLAYER1:
            col = int(input("Player 1, make your selection (0-6): "))
        else:
            col = int(input("Player 2, make your selection (0-6): "))

        if is_valid_location(board, col):
            row = get_next_open_row(board, col)
            drop_piece(board, row, col, turn)

            if winning_move(board, turn):
                print_board(board)
                print(f"Player {turn} wins!")
                game_over = True

            turn = PLAYER2 if turn == PLAYER1 else PLAYER1

        else:
            print("Invalid move. Try again.")

if __name__ == "__main__":
    main()
```

This code defines a basic Connect-4 game where two players take turns dropping their pieces into columns on a 6x7 grid. The game checks for a winner after each move by looking for four consecutive pieces horizontally, vertically, or diagonally.

To run this script, you need to have Python installed along with the NumPy library (`pip install numpy`). Enjoy playing Connect-4! If you want to add more features like AI opponents or graphical user interface, let me know!

